import json
from pathlib import Path
from collections import Counter
ROOT=Path(__file__).resolve().parents[1]
def main():
 p=ROOT/'data/processed';pages=json.loads((p/'extraction_quality.json').read_text());chunks=json.loads((p/'chunks.json').read_text(encoding='utf-8'));stats=json.loads((p/'chunk_statistics.json').read_text());review=json.loads((ROOT/'data/raw/source_review.json').read_text(encoding='utf-8'))
 lines=['# Extraction quality report','','Source: FG Wilson Generator Set Operator & Maintenance Instruction Manual, 356-5901(GB), V15 10/21. All 81 pages were extracted with PyMuPDF; raw text, bounding boxes, font attributes, table cells, source identity/hash and printed-page information are retained.','',f'Total extracted text characters: {sum(x["characters"] for x in pages):,}. Native text weak pages: '+', '.join(str(x['page']) for x in pages if 'weak_text' in x['issues'])+'.', '', 'Pages 55–56 contain image-only fault tables; page 55 has enough surrounding text to evade a text-length-only detector. Visual inspection caught this. Seventeen table rows were transcribed with source-hash locking. Pages 2, 79, 80 and 81 contain only blank/notes material. Image-bearing pages are flagged even when the text layer is strong. An image flag records the review obligation; it does not mean all content on that page is unusable. No weak page is silently discarded.','', 'Printed footer digits appear twice in the text layer. The original raw text is retained; the separate printed-page field records the visually confirmed footer (2–81), with no number inferred for the cover. The source page images/contact sheets are local inspection artifacts, not alternative authoritative manuals.','', 'FG100 icon-dependent instructions, diagram-dependent lifting instructions, illustrative plate/declaration data and identified source ambiguities are quarantined via source_review.json. Transcription and visual review are agent-performed; independent technical QA remains outstanding.','', '| PDF page | Printed page | Characters | Images | Native tables | Flags / resolution |','|---:|---|---:|---:|---:|---|']
 for x in pages:lines.append(f'| {x["page"]} | {x["printed_page"] or "unnumbered"} | {x["characters"]} | {x["images"]} | {x["tables"]} | {", ".join(x["issues"]) or "text extracted"}; {x["resolution"]} |')
 (ROOT/'docs/EXTRACTION_QUALITY_REPORT.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
 lines=['# Chunk quality report','',f'Total: **{stats["total"]}** chunks; **{stats["quarantined"]}** quarantined, **{stats["total"]-stats["quarantined"]}** eligible. All IDs are unique and deterministic SHA-256 derivatives of source hash, page range and exact chunk text.','', 'Chunks retain source document/title/revision/hash, stated applicability, controller scope, primary category, hazards, qualified-service indication, PDF range, printed pages and inherited warning page references. Complete numbered procedures remain in one section unit, including pre-start steps 1–14 across pages 36–37. Table rows are serialized with column labels; multi-symptom source cells are not split into invented independent diagnoses. Tables are ordered by coordinates and continuation headers are preserved.','', f'{stats["over_2600_characters"]} chunks exceed the advisory 2,600-character target; the largest is {stats["max_characters"]:,} characters. Preserving procedures takes precedence over arbitrary length. Overlapping embedding windows are separate retrieval representations, not modified answer evidence.','', '| Primary category | Total | Eligible | Representative inspected source |','|---|---:|---:|---|']
 for cat,count in sorted(stats['categories'].items()):
  cs=[c for c in chunks if c['category']==cat];eligible=[c for c in cs if not c['review_required']];sample=(eligible or cs)[0]
  lines.append(f'| {cat} | {count} | {len(eligible)} | {sample["section"]}; PDF {sample["page_start"]}–{sample["page_end"]}; `{sample["chunk_id"]}` |')
 lines+=['','Representative excerpts from every primary category were inspected against the previously read source text. Critical procedures, both ten-row PowerWizard tables, the seventeen DeepSea image rows, maintenance warnings and page transitions received additional inspection/tests. This is not independent human service approval.','', 'Topic coverage without inventing extra standalone chunks: air-intake checks occur in 5.1.1 and 6.3.1; automatic operation in controller subsections; symptoms and corrective actions in fault-finding rows; likely-cause information only where the source explicitly supplies it. Preventive maintenance, lubrication, cooling, fuel, exhaust, battery, alternator, electrical checks, storage and escalation have primary categories or embedded source-supported coverage. No separate fault-code chunk is fabricated: this manual has no numeric code dictionary.','', 'PowerWizard: 10 rows at page 45 and 10 at page 52. DeepSea: 9 source rows at page 55 and 8 at page 56. Additional critical-failure rows occur in section 4.6.2. The fault-finding category count also includes introductory section context, so it is not a fault-code count.','', 'Known limits: large mixed-topic sections can produce less concise excerpts; semantic windows may truncate unusually dense tokens; inherited and retrieved safety context is not an exhaustive warning-recall guarantee; column association for quarantined illustrative tables is not promoted to authoritative specifications.','', '## Quarantined section reasons','']
 for section,reason in review['quarantined_sections'].items():lines.append(f'- {section}: {reason}')
 (ROOT/'docs/CHUNK_QUALITY_REPORT.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
if __name__=='__main__':main()
